classdef ReportTables
    % REPORTTABLES  Read the tables of a machine-generated Markdown experiment report.
    %
    %   r = OceanViz.App.NLP.SpeechStudio.Models.ReportTables.read(file)
    %     r.File       absolute path of the report
    %     r.Generator  the "Generated by `<script>` on <date>" sentence ("" if absent)
    %     r.Title      first "# " heading
    %     r.Tables     struct array: Heading (nearest preceding "#..." heading), Line
    %                  (1-based line of the header row), Header (1 x C string), Rows (R x C string)
    %
    %   Only reports with a "Generated by" line are accepted (r = read(file) errors
    %   otherwise): the studio shows numbers that scripts computed, never prose typed by
    %   hand. A table is a header row "| a | b |", a separator row "| --- | ---: |" and
    %   the following "|"-rows; cells are kept as the literal text of the report.

    methods (Static)
        function r = read(file)
            arguments
                file (1,1) string {mustBeFile}
            end
            lines = string(readlines(file));
            gen = lines(contains(lines, "Generated by"));
            if isempty(gen)
                error('OceanViz:App:NLP:SpeechStudio:ReportTables:NotGenerated', ...
                    '%s has no "Generated by" line; only machine-generated reports are read.', file);
            end
            r.File = string(file);
            r.Generator = strip(gen(1));
            heads = find(startsWith(lines, "#"));
            r.Title = "";
            if ~isempty(heads), r.Title = strip(regexprep(lines(heads(1)), '^#+', '')); end
            r.Tables = struct('Heading', {}, 'Line', {}, 'Header', {}, 'Rows', {});
            isRow = startsWith(strip(lines), "|");
            isSep = ~cellfun(@isempty, regexp(cellstr(strip(lines)), '^\|(\s*:?-{3,}:?\s*\|)+\s*$', 'once'));
            i = 1;
            n = numel(lines);
            while i < n
                if isRow(i) && isSep(i + 1)
                    header = OceanViz.App.NLP.SpeechStudio.Models.ReportTables.cells(lines(i));
                    j = i + 2;
                    rows = strings(0, numel(header));
                    while j <= n && isRow(j) && ~isSep(j)
                        c = OceanViz.App.NLP.SpeechStudio.Models.ReportTables.cells(lines(j));
                        c(end+1:numel(header)) = "";
                        rows(end+1, :) = c(1:numel(header)); %#ok<AGROW>
                        j = j + 1;
                    end
                    h = heads(heads < i);
                    heading = r.Title;
                    if ~isempty(h), heading = strip(regexprep(lines(h(end)), '^#+', '')); end
                    r.Tables(end+1) = struct('Heading', heading, 'Line', i, 'Header', header, 'Rows', rows);
                    i = j;
                else
                    i = i + 1;
                end
            end
        end

        function c = cells(line)
            % CELLS  The cells of one "| a | b |" row (outer pipes removed, trimmed).
            s = strip(line);
            s = regexprep(s, '^\|', '');
            s = regexprep(s, '\|$', '');
            s = replace(s, "\|", char(1));            % escaped pipe inside a cell
            c = strip(split(s, "|"))';
            c = replace(replace(c, "`", ""), char(1), "|");
        end
    end
end
